'use strict';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='pl';try{lang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('agnieszka-language')||'pl';}catch{}
lang=lang==='en'?'en':'pl';
// 20.11.2026: the design is settled on V2. The "Wersja V1 / V2" pill is gone and the version is fixed to '2' (a stored or ?v=1 choice from the
// earlier review rounds is ignored, so nobody can end up on V1 without a way back). The V1 code below (homeBlocks, homeSections, versionSwitcher,
// setVersion) is kept in the file but is no longer reachable.
let version='2';
try{localStorage.setItem('agnieszka-home-version','2');}catch{}
const tr=(pl,en)=>lang==='en'?en:pl;
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 12h15M13 5l7 7-7 7"/></svg>';
const menuIcon='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 8h16M4 16h16"/></svg>';
const bookButton=(label,id='help',style='')=>`<button class="button ${style}" data-book="${esc(id)}">${label}<span class="arrow">${arrow}</span></button>`;
function header(){return `<a class="skip" href="#main">${tr('Przejdź do treści','Skip to content')}</a><header class="site-header"><a class="brand" href="/#top">agnieszka clarity</a><nav class="nav-links" aria-label="${tr('Menu główne','Main menu')}"><a href="/#o-mnie">${tr('O mnie','About me')}</a><a href="/#sesje">${tr('Sesje 1:1','1:1 sessions')}</a><a href="/#joga">${tr('Studio Jogi','Studio Jogi')}</a><a href="/warsztaty/">${tr('Warsztaty','Workshops')}</a><a href="/sklep/">${tr('Sklep','Shop')}</a><a href="/#najblizsze">${tr('Wydarzenia','Events')}</a></nav><button class="language" data-language aria-label="${tr('Zmień język na angielski','Switch language to Polish')}">${lang==='pl'?'PL / EN':'EN / PL'}</button><button class="button nav-cta" data-book="help">${tr('Umów sesję','Book a session')}</button><button class="menu-toggle" aria-label="${tr('Otwórz menu','Open menu')}" aria-expanded="false">${menuIcon}</button></header><nav class="mobile-nav" aria-label="${tr('Menu mobilne','Mobile menu')}"><a href="/#o-mnie">${tr('O mnie','About me')}</a><a href="/#sesje">${tr('Sesje 1:1','1:1 sessions')}</a><a href="/#joga">${tr('Studio Jogi','Studio Jogi')}</a><a href="/warsztaty/">${tr('Warsztaty','Workshops')}</a><a href="/sklep/">${tr('Sklep','Shop')}</a><a href="/#najblizsze">${tr('Wydarzenia','Events')}</a><button class="button" data-book="help">${tr('Umów sesję','Book a session')}</button></nav>`;}
function homeHero(){return `<section class="hero" aria-labelledby="hero-title"><img class="hero-photo" src="/assets/hero-open-sky.png" width="1706" height="922" alt="${tr('Kobieta z otwartymi ramionami nad wodą','A woman with open arms by the water')}" fetchpriority="high"><h1 id="hero-title"><span>${tr('Zatrzymaj się.','Pause.')}</span><span>${tr('Poczuj siebie.','Tune in to yourself.')}</span></h1><div class="hero-intro"><p class="hero-methods">${tr('Sesje 1:1 · Joga · Medytacja','1:1 sessions · Yoga · Meditation')}</p><p>${tr('Przestrzeń na spotkanie<br>z emocjami, ciałem i sobą.','A space to connect<br>with your emotions, your body and yourself.')}</p>${bookButton(tr('Umów sesję 1:1','Book a 1:1 session'),'session','light')}</div><aside class="hero-note"><p class="note-label">${tr('SESJE 1:1 · JOGA · MEDYTACJA','1:1 SESSIONS · YOGA · MEDITATION')}</p><h2>${tr('Czas czuć.','Time to feel.')}</h2><p class="note-copy">${tr('W swoim tempie.','At your own pace.')}</p><span class="note-rule" aria-hidden="true"></span></aside></section><section class="philosophy"><h2><span>${tr('Nie musisz mieć wszystkiego poukładanego,','You don\'t need to have everything figured out')}</span> <span class="soft">${tr('żeby zacząć słuchać siebie.','to start listening to yourself.')}</span></h2></section>`;}
const services=[
 {id:'help',pl:'Potrzebuję pomocy w wyborze',en:'I\'d like help choosing'},
 {id:'session',pl:'Sesja indywidualna 1:1',en:'Individual 1:1 session'},
 {id:'kundalini',pl:'Joga Kundalini',en:'Kundalini yoga'},
 {id:'mantra',pl:'Moc mantry i wibracji',en:'The power of mantra and vibration'},
 {id:'flow',pl:'Joga Flow',en:'Flow yoga'},
 {id:'combo',pl:'Kundalini + Flow',en:'Kundalini + Flow'},
 {id:'discover',pl:'Odkryj siebie — cykl 12 warsztatów',en:'Discover yourself — a series of 12 workshops'},
 {id:'mind',pl:'Aktywacja mózgu, klarowność umysłu',en:'Brain activation, mental clarity'},
 {id:'karma',pl:'Karma — masterclass',en:'Karma — masterclass'},
 {id:'life',pl:'Życiowe lekcje — masterclass',en:'Life lessons — masterclass'},
 {id:'money',pl:'Energia pieniądza — masterclass',en:'The energy of money — masterclass'}
];
const label=id=>{const s=services.find(x=>x.id===id);return s?s[lang]:id;};
const programs=[
 {id:'discover',img:'v2/gallery/discover-mandala-green.jpg',tone:'straw',pl:'Zatrzymaj się przy tym, co dla Ciebie ważne. Cykl spotkań, praktyki i refleksji nad różnymi obszarami życia.',en:'Take a moment for what matters to you. A series of sessions, practices and reflections on different areas of life.'},
 {id:'mind',img:'v2/gallery/mind-mandala-lavender.jpg',tone:'mint',pl:'Przestrzeń na uważność, koncentrację i spokojniejsze spotkanie z własnymi myślami.',en:'Space for mindfulness, focus and a calmer relationship with your thoughts.'},
 {id:'karma',img:'v2/gallery/karma-mandala-sand-fade.jpg',tone:'lavender',pl:'Spotkanie poświęcone wyborom, powtarzającym się schematom i osobistej perspektywie.',en:'A session exploring choices, recurring patterns and your personal perspective.'},
 {id:'life',img:'v2/gallery/life-mandala-sky.jpg',tone:'straw',pl:'Zobacz własne doświadczenia z nowej perspektywy. Czas na pytania, rozmowę i refleksję.',en:'See your experiences from a new perspective. Time for questions, conversation and reflection.'},
 {id:'money',img:'v2/gallery/money-mandala-olive-fade.jpg',tone:'mint',pl:'Warsztat refleksji nad przekonaniami i osobistą relacją z pieniędzmi.',en:'A workshop to reflect on beliefs and your personal relationship with money.'}
];
// Example dates belong only to this local prototype, not to a confirmed calendar.
const events=[
 {id:'demo-breath',service:'session',date:'2026-12-05',pl:'Oddech i uważność',en:'Breath and mindfulness',format:'online',img:'agnieszka-meditation.jpg',status:'open'},
 {id:'demo-discover',service:'discover',date:'2026-12-12',pl:'Odkryj siebie',en:'Discover yourself',format:'online',img:'workshop.jpg',status:'soon'},
 {id:'demo-yoga',service:'kundalini',date:'2027-01-09',pl:'Poranek z jogą',en:'Morning yoga',format:'studio',img:'joga.jpg',status:'open'},
 {id:'demo-archive',service:'mind',date:'2026-10-10',pl:'Spokojny umysł',en:'A calm mind',format:'online',img:'agnieszka-beach.jpg',status:'ended'}
];
const dateText=d=>new Intl.DateTimeFormat(lang==='en'?'en-GB':'pl-PL',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Warsaw'}).format(new Date(d+'T12:00:00+01:00'));
const img=(name,alt,cls='')=>`<img class="${cls}" src="/assets/${name}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
const detail=(id,title,body)=>`<details id="${id}"><summary>${title}<span class="plus" aria-hidden="true"></span></summary><div class="detail-body">${body}</div></details>`;
function eventCard(e,compact=false){const ended=e.status==='ended';return `<article class="event-card ${compact?'compact':''}">${compact?'':img(e.img,e[lang])}<div class="event-content"><div class="event-meta"><span>${tr('Przykładowa data','Example date')}</span><time datetime="${e.date}">${dateText(e.date)}</time></div><h3>${e[lang]}</h3><p>${e.format==='online'?tr('Spotkanie online','Online session'):tr('Praktyka w studio','Studio practice')}</p><div class="event-bottom"><span class="status ${ended?'ended':''}">${ended?tr('Zakończone','Ended'):e.status==='soon'?tr('Zapisy wkrótce','Registration opens soon'):tr('Przykład otwartego zapisu','Example: registration open')}</span>${ended?`<button class="text-link" data-info="archive">${tr('Zobacz opis','View details')}</button>`:`<button class="round-link" data-book="${e.service}" data-event="${e.id}" aria-label="${esc(tr('Zapytaj o: ','Ask about: ')+e[lang])}">${arrow}</button>`}</div></div></article>`;}
// Home V1 blocks. Client edit 12.11.2026: Terapia, Szkoła Klarowności, Wydarzenia and Blog are hidden from the page.
// Their code stays here so a block can return by adding its key back to homeOrder.
const homeBlocks={
about:()=>`<section id="o-mnie" class="section container about"><div class="portrait-wrap">${img('agnieszka-portrait.jpg',tr('Agnieszka na kanapie w jasnym wnętrzu','Agnieszka on a sofa in a bright interior'))}<span class="photo-caption">${tr('Z uważnością. Po ludzku.','With mindfulness. With warmth.')}</span></div><div class="section-copy"><h2>${tr('Dobrze, że jesteś.','I\'m glad you\'re here.')}</h2><p class="lead">${tr('Jestem Agnieszka. Towarzyszę w spotkaniu z emocjami, ciałem i własnym doświadczeniem.','I\'m Agnieszka. I support you as you explore your emotions, your body and your own experience.')}</p><p>${tr('Łączę pracę indywidualną z praktyką jogi i medytacji. Tworzę przestrzeń, w której możesz zatrzymać się, porozmawiać i poszukać własnego tempa.','I combine one-to-one work with yoga and meditation. I create a space where you can pause, talk and find your own pace.')}</p><div class="accordion-group">${detail('about-details',tr('Poznaj moje podejście','Explore my approach'),`<p>${tr('Punktem wyjścia jest rozmowa i Twoje potrzeby. Formę współpracy ustalamy wspólnie. Ten opis jest tekstem roboczym do zatwierdzenia przez Agnieszkę.','We start with a conversation about your needs. Together, we agree on the form of support. This description is a draft for Agnieszka to approve.')}</p>`)}</div><a class="text-link" href="#sesje">${tr('Poznaj możliwości spotkania','Explore session options')}${arrow}</a></div></section>`,
sessions:()=>`<section id="sesje" class="section container editorial"><div class="section-copy"><h2>${tr('Czas tylko<br>dla Ciebie.','Time just<br>for you.')}</h2><p class="lead">${tr('Sesje indywidualne 1:1','Individual 1:1 sessions')}</p><p>${tr('Nie musisz wiedzieć, od czego zacząć. Pierwszy krok to krótka wiadomość. Wspólnie ustalimy, jaki rodzaj spotkania odpowiada Twoim potrzebom.','You don\'t have to know where to start. The first step is a short message. Together, we\'ll work out what kind of session suits your needs.')}</p><div class="accordion-group">${detail('session-first',tr('Jak wygląda pierwszy krok?','How do I get started?'),`<p>${tr('Wybierz usługę w formularzu lub poproś o pomoc w wyborze. Termin, miejsce i szczegóły spotkania potwierdzimy w osobnym kontakcie.','Choose a service in the form or ask for help choosing. We will confirm the time, location and session details when we get in touch.')}</p>`)}${detail('session-format',tr('Online czy stacjonarnie?','Online or in person?'),`<p>${tr('Dostępny format, czas trwania i warunki ustalimy przed spotkaniem. Aktualne szczegóły zostaną uzupełnione w finalnej wersji strony.','We will agree on the available format, duration and arrangements before the session. Up-to-date details will be added to the final version of the site.')}</p>`)}</div>${bookButton(tr('Zapytaj o sesję 1:1','Ask about a 1:1 session'),'session')}</div>${img('brainspotting.jpg',tr('Indywidualne spotkanie w jasnym gabinecie','A one-to-one session in a bright room'),'editorial-photo')}</section>`,
therapy:()=>`<section id="terapia" class="section therapy container"><div class="section-heading"><h2>${tr('Blisko emocji.<br>Blisko siebie.','Closer to your emotions.<br>Closer to yourself.')}</h2><p>${tr('Poznaj dwa kierunki pracy indywidualnej. Rozwiń opis, by dowiedzieć się więcej i zapytać o spotkanie.','Explore two approaches to one-to-one work. Expand a description to learn more and ask about a session.')}</p></div><div class="therapy-layout">${img('agnieszka-meditation.jpg',tr('Agnieszka podczas medytacji na łonie natury','Agnieszka meditating outdoors in nature'))}<div class="therapy-list"><article><h3>Brainspotting</h3><p>${tr('Indywidualna praca z doświadczeniem, emocjami i sygnałami z ciała.','One-to-one work with your experience, emotions and signals from the body.')}</p><div class="accordion-group">${detail('brain-details',tr('Na czym polega spotkanie?','What does a session involve?'),`<p>${tr('Podczas kontaktu omówimy, z czym przychodzisz i jak może wyglądać sesja. Przed rozpoczęciem wyjaśnimy metodę i odpowiemy na pytania.','When we get in touch, we\'ll discuss what brings you here and what a session might look like. Before we begin, we\'ll explain the approach and answer your questions.')}</p>`)}</div><button class="text-link" data-book="brainspotting">${tr('Zapytaj o Brainspotting','Ask about Brainspotting')}${arrow}</button></article><article><h3>Energy Mind Healing</h3><p>${tr('Praktyka obecna w ofercie Agnieszki, łącząca uwagę na ciało, oddech i osobiste doświadczenie.','A practice offered by Agnieszka that brings together attention to the body, breathing and personal experience.')}</p><div class="accordion-group">${detail('energy-details',tr('Dowiedz się więcej','Find out more'),`<p>${tr('Zakres i przebieg spotkania zostaną wyjaśnione w rozmowie. Szczegółowy opis metody wymaga zatwierdzenia przed publikacją strony.','The scope and structure of the session will be explained in a conversation. A detailed description of the method needs approval before the site is published.')}</p>`)}</div><button class="text-link" data-book="energy">${tr('Zapytaj o spotkanie','Ask about a session')}${arrow}</button></article></div></div></section>`,
yoga:()=>`<section id="joga" class="section wide color-split mint">${img('joga.jpg',tr('Praktyka jogi w jasnym studio','Yoga practice in a bright studio'))}<div class="section-copy"><h2>${tr('Ruch. Oddech.<br>Obecność.','Movement. Breath.<br>Presence.')}</h2><p class="lead">Studio Jogi</p><p>${tr('Wybierz praktykę, która jest Ci bliska. Mniej pośpiechu, więcej miejsca na własne doświadczenie.','Choose a practice that feels right for you. Less rushing, more space for your own experience.')}</p><div class="accordion-group">${['kundalini','flow','combo'].map(id=>detail('yoga-'+id,label(id),`<p>${id==='kundalini'?tr('Praktyka łącząca ruch, oddech i medytację.','A practice combining movement, breathing and meditation.'):id==='flow'?tr('Płynna praktyka ruchu i oddechu.','A flowing practice of movement and breath.'):tr('Połączenie dwóch stylów praktyki.','A combination of two styles of practice.')}</p><button class="text-link" data-book="${id}">${tr('Zapytaj o praktykę','Ask about classes')}${arrow}</button>`)).join('')}</div></div></section>`,
upcoming:()=>`<section id="najblizsze" class="section container"><div class="section-heading"><h2>${tr('Spotkajmy się.','Let\'s meet.')}</h2><p>${tr('Najbliższe wydarzenia z kalendarza. W prototypie — przykładowe dane w miejscu wtyczki.','Upcoming events from the calendar. In this prototype, example data stands in for the calendar plugin.')}</p></div><div class="events-grid upcoming">${events.filter(e=>e.status!=='ended').map(e=>eventCard(e,true)).join('')}</div></section>`,
workshops:()=>`<section id="warsztaty" class="section container workshop-feature"><div class="section-copy"><h2>${tr('Odkrywaj.<br>Doświadczaj.','Explore.<br>Experience.')}</h2><p class="lead">${tr('Warsztaty i wspólna praktyka','Workshops and shared practice')}</p><p>${tr('Programy, które zapraszają do refleksji, rozmowy i spotkania z własnym doświadczeniem. Poznaj wszystkie kierunki.','Programmes that invite reflection, conversation and exploration of your own experience. Discover all the options.')}</p><ul class="program-index">${programs.map(p=>`<li><a href="/warsztaty/#${p.id}">${label(p.id)}${arrow}</a></li>`).join('')}</ul><a class="button" href="/warsztaty/">${tr('Zobacz warsztaty','View workshops')}</a></div><figure>${img('workshop.jpg',tr('Swobodny ruch na plaży o zachodzie słońca','Free movement on the beach at sunset'))}<figcaption class="straw"><h3>${tr('Odkryj siebie.','Discover yourself.')}</h3><p>${tr('Cykl 12 warsztatów.','A series of 12 workshops.')}</p></figcaption></figure></section>`,
school:()=>`<section id="szkola" class="section wide school lavender"><div class="section-copy"><h2>${tr('Szkoła<br>Klarowności.','School of<br>Clarity.')}</h2><p class="lead">${tr('Miejsce na głębszą praktykę i naukę.','A space for deeper practice and learning.')}</p><p>${tr('Poznaj kierunek edukacyjny Agnieszki. Napisz, jeśli chcesz otrzymać informacje o programie i kolejnych spotkaniach.','Explore Agnieszka\'s educational programme. Get in touch if you\'d like information about the programme and upcoming sessions.')}</p>${bookButton(tr('Zapytaj o program','Ask about the programme'),'school')}</div>${img('agnieszka-beach.jpg',tr('Agnieszka praktykuje jogę na plaży','Agnieszka practising yoga on the beach'))}</section>`,
events:()=>`<section id="wydarzenia" class="section container"><div class="section-heading"><h2>${tr('Wspólne<br>doświadczenia.','Shared<br>experiences.')}</h2><p>${tr('Wydarzenia online, praktyki i spotkania. Pokazane terminy są przykładowe.','Online events, practices and sessions. The dates shown are examples.')}</p></div><div class="filter-row" aria-label="${tr('Filtruj wydarzenia','Filter events')}"><button class="filter active" data-event-filter="all" aria-pressed="true">${tr('Wszystkie','All')}</button><button class="filter" data-event-filter="online" aria-pressed="false">Online</button><button class="filter" data-event-filter="studio" aria-pressed="false">${tr('W studio','In the studio')}</button><button class="filter" data-event-filter="ended" aria-pressed="false">${tr('Archiwum','Archive')}</button></div><div class="events-grid event-results">${events.map(e=>eventCard(e)).join('')}</div></section>`,
blog:()=>`<section id="blog" class="section container blog"><div class="section-heading"><h2>${tr('Chwila<br>na refleksję.','A moment<br>for reflection.')}</h2><p>${tr('Blog — podgląd tematów z materiałów. Teksty robocze.','Blog — a preview of topics from the source materials. Draft texts.')}</p></div><div class="blog-grid">${[['joga.jpg',tr('Ruch, oddech i chwila dla siebie','Movement, breath and a moment for yourself')],['brainspotting.jpg',tr('Jak przygotować się do pierwszej rozmowy','How to prepare for your first conversation')],['agnieszka-meditation.jpg',tr('Uważność w codzienności','Mindfulness in everyday life')]].map(([photo,title],i)=>`<button class="blog-card" data-info="article-${i}">${img(photo,title)}<span>${tr('Materiał w przygotowaniu','Content in preparation')}</span><h3>${title}</h3><span class="blog-arrow">${arrow}</span></button>`).join('')}</div></section>`,
shop:()=>shopTeaser()
};
const homeOrder=['about','sessions','yoga','workshops','upcoming'];
function homeSections(){return homeOrder.map(k=>homeBlocks[k]()).join('');}
function contact(){return `<section id="kontakt" class="section wide contact straw"><div class="section-copy"><h2>${tr('Zacznijmy<br>od rozmowy.','Let\'s start<br>with a conversation.')}</h2><p>${tr('Nie musisz od razu wybierać metody. Napisz, a wspólnie ustalimy pierwszy krok.','You don\'t have to choose a method straight away. Get in touch and we\'ll work out the first step together.')}</p>${bookButton(tr('Napisz do mnie','Get in touch'))}</div>${img('agnieszka-portrait.jpg',tr('Portret Agnieszki','A portrait of Agnieszka'))}</section>`;}
function footer(){return `<footer class="site-footer"><span class="footer-flower" aria-hidden="true"><img src="/assets/v2/ornaments/botanical-flower.svg" alt="" width="1059" height="1054" loading="lazy"></span><p class="footer-statement" aria-hidden="true">${tr('Bliżej siebie.<br>Bliżej życia.','Closer to yourself.<br>Closer to life.')}</p><div class="footer-top"><div><a class="brand" href="/#top">agnieszka clarity</a><p>${tr('Przestrzeń na spotkanie<br>z emocjami, ciałem i sobą.','A space to connect<br>with your emotions, your body and yourself.')}</p></div><nav aria-label="${tr('Oferta','What I offer')}"><h3>${tr('Spotkania','Sessions')}</h3><a href="/#sesje">${tr('Sesje 1:1','1:1 sessions')}</a><a href="/#joga">${tr('Studio Jogi','Studio Jogi')}</a><a href="/warsztaty/">${tr('Warsztaty','Workshops')}</a><a href="/#najblizsze">${tr('Wydarzenia','Events')}</a></nav><nav aria-label="${tr('Informacje','Information')}"><h3>${tr('Warto wiedzieć','Good to know')}</h3><a href="/#kontakt">${tr('Kontakt','Contact')}</a><a href="/sklep/">${tr('Sklep','Shop')}</a><button data-info="rules">${tr('Regulamin','Terms and conditions')}</button><button data-info="privacy">${tr('Polityka prywatności','Privacy policy')}</button></nav><div class="footer-events"><h3>${tr('Najbliższe spotkanie','Next session')}</h3><p class="demo-caption">${tr('Przykład w prototypie','Prototype example')}</p><button data-book="${events[0].service}" data-event="${events[0].id}"><time datetime="${events[0].date}">${dateText(events[0].date)}</time><span>${events[0][lang]} ${arrow}</span></button></div></div><div class="footer-bottom"><span>© 2026 agnieszka clarity</span><span>${tr('Prototyp do uzgodnienia · Bez zakupów i wysyłki danych','Prototype for review · No purchases or data submission')}</span></div></footer>`;}
function workshopsPage(){const v2=version==='2';return `${v2?v2PageHero('workshops'):`<section class="page-intro container"><h1>${tr('Przestrzeń<br>do odkrywania.','Space<br>to explore.')}</h1><div><p class="lead">${tr('Warsztaty','Workshops')}</p><p>${tr('Praktyka, refleksja i wspólne doświadczenie. Poznaj programy i znajdź temat, który jest Ci teraz bliski.','Practice, reflection and shared experience. Explore the programmes and find a topic that speaks to you right now.')}</p></div></section>`}<nav id="programy" class="program-jumps container" aria-label="${tr('Programy warsztatów','Workshop programmes')}">${programs.map(p=>`<a href="#${p.id}">${label(p.id)}${arrow}</a>`).join('')}</nav><div class="programs container">${programs.map((p,i)=>`<section id="${p.id}" class="program-section ${i%2?'reverse':''}"><div class="program-photo ${p.tone}">${img(p.img,label(p.id))}</div><div class="section-copy"><h2>${label(p.id)}</h2><p class="lead">${p[lang]}</p><p class="availability">${tr('Termin i szczegóły do ustalenia','Date and details to be arranged')}</p><div class="accordion-group">${detail(p.id+'-program',tr('Program warsztatu','Workshop programme'),`<p>${tr('Wprowadzenie do tematu, wspólna praktyka, czas na pytania i samodzielną refleksję. Dokładny program zostanie zatwierdzony przed publikacją.','An introduction to the topic, shared practice, time for questions and personal reflection. The full programme will be approved before publication.')}</p>`)}${detail(p.id+'-audience',tr('Dla kogo?','Who is it for?'),`<p>${tr('Dla osób zainteresowanych tym tematem. Przed zgłoszeniem możesz zapytać o format, wymagania i przebieg spotkania.','For anyone interested in this topic. Before signing up, you can ask about the format, requirements and what the session involves.')}</p>`)}</div>${bookButton(tr('Zapytaj o udział','Ask about joining'),p.id)}</div></section>`).join('')}</div>${v2?`<section id="najblizsze" class="v2-section v2-container v2-upcoming"><div class="v2-section-top"><h2>${tr('Praktyka<br>w dobrym towarzystwie.','Practice<br>in good company.')}</h2><p>${tr('Przykładowe nadchodzące wydarzenia.','Examples of upcoming events.')}</p></div><div class="v2-event-cards">${v2EventCards(events.filter(e=>e.status!=='ended'))}</div></section>`:`<section class="container section"><div class="section-heading"><h2>${tr('Praktyka<br>w dobrym towarzystwie.','Practice<br>in good company.')}</h2><p>${tr('Przykładowe nadchodzące wydarzenia.','Examples of upcoming events.')}</p></div><div class="events-grid">${events.slice(0,3).map(e=>eventCard(e,true)).join('')}</div></section>`}`;}
// ---- Shop (demo catalog, no purchases) -------------------------------------------------
// Prices come from the client's "Sklep v1.pdf" mock and are shown as examples only.
const shopIcons={
 screen:'<rect x="3" y="4.5" width="18" height="12" rx="1.5"/><path d="M8.5 20h7M12 16.5V20M7 8.5h6M7 11.5h10"/>',
 lotus:'<path d="M12 4.5c-2.6 3-2.6 8.2 0 12.5 2.6-4.3 2.6-9.5 0-12.5Z"/><path d="M12 17c-4.2 0-7.6-2.4-9-6 3.6-.4 6.8 1.6 9 6Zm0 0c4.2 0 7.6-2.4 9-6-3.6-.4-6.8 1.6-9 6Z"/><path d="M5 20h14"/>',
 book:'<path d="M12 6.5C10 5 7 4.5 3.5 5v13c3.5-.5 6.5 0 8.5 1.5 2-1.5 5-2 8.5-1.5V5C17 4.5 14 5 12 6.5Z"/><path d="M12 6.5v13"/>'
};
const shopIcon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linejoin="round" stroke-linecap="round">${shopIcons[name]}</svg>`;
const shopCats=[
 {id:'all',pl:'Wszystko',en:'All'},
 {id:'workshops',pl:'Warsztaty online',en:'Online workshops',icon:'screen',format:{pl:'Warsztat online',en:'Online workshop'}},
 {id:'yoga',pl:'Joga',en:'Yoga',icon:'lotus',format:{pl:'Praktyka jogi',en:'Yoga practice'}},
 {id:'ebooks',pl:'E-booki',en:'E-books',icon:'book',format:{pl:'E-book',en:'E-book'}}
];
const products=[
 {id:'discover',cat:'workshops',price:250},
 {id:'mantra',cat:'yoga',price:280,pl:'Doświadczenie jogi kundalini poprzez dźwięk, mantrę i medytację.',en:'Experience Kundalini yoga through sound, mantra and meditation.'},
 {id:'mind',cat:'workshops',price:240},
 {id:'life',cat:'workshops',price:250},
 {id:'kundalini',cat:'yoga',price:240,pl:'Praktyka łącząca ruch, oddech i medytację. Dla osób, które chcą poczuć więcej energii i spokoju.',en:'A practice combining movement, breathing and meditation. For anyone who would like to feel more energised and at ease.'},
 {id:'money',cat:'workshops',price:240}
];
const catOf=p=>shopCats.find(c=>c.id===p.cat);
const productText=p=>p[lang]||programs.find(x=>x.id===p.id)?.[lang]||'';
const priceText=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN',maximumFractionDigits:0}).format(n);
const countText=n=>{const r=new Intl.PluralRules(lang==='en'?'en-GB':'pl-PL').select(n);const w=lang==='en'?{one:'product',few:'products',many:'products',other:'products'}:{one:'produkt',few:'produkty',many:'produktów',other:'produktu'};return `${n} ${w[r]}`;};
const productUrl=id=>`/sklep/?produkt=${encodeURIComponent(id)}`;
function shopFilterKey(){let k='all';try{k=new URLSearchParams(location.search).get('kategoria')||'all';}catch{}return shopCats.some(c=>c.id===k)?k:'all';}
function productMedia(p,size=''){const c=catOf(p);return `<div class="product-media ${size}"><span class="product-badge">${c.format[lang]}</span>${shopIcon(c.icon,'product-icon')}<span class="visually-hidden">${tr('Miejsce na zdjęcie produktu','Product photo placeholder')}</span></div>`;}
function productCard(p,h='h2'){return `<article class="product-card">${productMedia(p)}<div class="product-body"><${h} class="product-title"><a href="${productUrl(p.id)}">${label(p.id)}</a></${h}><p class="product-desc">${productText(p)}</p><div class="product-foot"><p class="product-price"><span class="price">${priceText(p.price)}</span><span class="price-note">${tr('Cena przykładowa','Example price')}</span></p><span class="product-go" aria-hidden="true">${arrow}</span></div></div></article>`;}
function shopProducts(filter,limit=99,h='h2'){const list=products.filter(p=>filter==='all'||p.cat===filter).slice(0,limit);return list.length?list.map(p=>productCard(p,h)).join(''):`<div class="empty-state">${shopIcon('book','empty-icon')}<h2>${tr('Jeszcze chwila.','Coming soon.')}</h2><p>${tr('E-booki pojawią się w sklepie wkrótce. Zajrzyj do warsztatów online albo praktyk jogi.','E-books will be available in the shop soon. In the meantime, explore the online workshops or yoga practices.')}</p><button class="text-link" data-shop-filter="all">${tr('Zobacz cały katalog','View the full catalogue')}${arrow}</button></div>`;}
function shopToolbar(active){const n=products.filter(p=>active==='all'||p.cat===active).length;return `<div class="shop-toolbar"><div class="filter-row" role="group" aria-label="${tr('Kategorie katalogu','Catalogue categories')}">${shopCats.map(c=>`<button class="filter ${c.id===active?'active':''}" data-shop-filter="${c.id}" aria-pressed="${c.id===active}">${c[lang]}</button>`).join('')}</div><p class="shop-count" aria-live="polite">${countText(n)}</p></div>`;}
function shopPage(){const k=shopFilterKey();return `${version==='2'?v2PageHero('shop'):`<section class="page-intro container"><h1>${tr('Dobre rzeczy<br>dla siebie.','Good things<br>for yourself.')}</h1><div><p class="lead">${tr('Sklep','Shop')}</p><p>${tr('Warsztaty online i praktyki do wykonania w swoim tempie. Katalog pokazowy: zakupy online nie są jeszcze dostępne.','Online workshops and practices to explore at your own pace. Demo catalogue: online purchases are not yet available.')}</p></div></section>`}<section id="katalog" class="container shop-section">${shopToolbar(k)}<div class="shop-grid">${shopProducts(k)}</div><p class="catalog-note">${tr('Ceny i produkty są przykładowe — pochodzą z makiety sklepu. Dostępność i oferta zostaną potwierdzone osobno.','Prices and products are examples taken from the shop mockup. Availability and the final range will be confirmed separately.')}</p></section>`;}
function applyShopFilter(key){$$('[data-shop-filter]').forEach(b=>{if(!b.closest('.filter-row'))return;b.classList.toggle('active',b.dataset.shopFilter===key);b.setAttribute('aria-pressed',String(b.dataset.shopFilter===key));});$('.shop-grid').innerHTML=shopProducts(key);const n=products.filter(p=>key==='all'||p.cat===key).length;const count=$('.shop-count');if(count)count.textContent=countText(n);try{const url=new URL(location.href);key==='all'?url.searchParams.delete('kategoria'):url.searchParams.set('kategoria',key);history.replaceState(null,'',url);}catch{}}
function shopProductId(){try{return new URLSearchParams(location.search).get('produkt');}catch{return null;}}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return `<section class="container product-missing"><h1>${tr('Nie znaleźliśmy<br>tego produktu.','We couldn\'t find<br>this product.')}</h1><p>${tr('Mógł zostać usunięty z katalogu albo adres jest niepełny.','It may have been removed from the catalogue, or the address may be incomplete.')}</p><a class="button" href="/sklep/">${tr('Wróć do sklepu','Back to the shop')}<span class="arrow">${arrow}</span></a></section>`;
 const c=catOf(p),title=label(p.id),bookable=services.some(s=>s.id===p.id);
 document.title=`${title} — ${tr('Sklep','Shop')} — agnieszka clarity`;
 const includes=p.cat==='yoga'?[tr('Praktyka prowadzona przez Agnieszkę','Practice led by Agnieszka'),tr('Wskazówki do samodzielnej praktyki w domu','Guidance for practising on your own at home'),tr('Możliwość zadania pytań przed zakupem','A chance to ask questions before buying')]:[tr('Udział w warsztacie online','Participation in an online workshop'),tr('Materiały do pracy własnej','Materials for independent work'),tr('Czas na pytania i refleksję','Time for questions and reflection')];
 const related=products.filter(x=>x.id!==p.id).sort((a,b)=>(b.cat===p.cat)-(a.cat===p.cat)).slice(0,3);
 return `<nav class="container breadcrumbs" aria-label="${tr('Ścieżka','Pathway')}"><ol><li><a href="/sklep/">${tr('Sklep','Shop')}</a></li><li><a href="/sklep/?kategoria=${p.cat}">${c[lang]}</a></li><li aria-current="page">${title}</li></ol></nav>
<section class="container product-detail"><div class="product-gallery">${productMedia(p,'large')}<p class="gallery-note">${tr('Miejsce na zdjęcia produktu','Product photos placeholder')}</p></div>
<div class="product-buy"><h1>${title}</h1><p class="product-lead">${productText(p)}</p>
<div class="buy-price"><span class="price">${priceText(p.price)}</span><span class="price-note">${tr('Cena przykładowa z makiety','Example price from the mockup')}</span></div>
<p class="availability-line"><span class="dot" aria-hidden="true"></span>${tr('Sprzedaż online wkrótce. Możesz już teraz zapytać o termin i dostęp.','Online sales are coming soon. You can already ask about dates and access.')}</p>
<button class="button buy-cta" data-book="${bookable?p.id:'help'}">${tr('Zapytaj o ten produkt','Ask about this product')}<span class="arrow">${arrow}</span></button>
<dl class="product-facts"><div><dt>${tr('Format','Format')}</dt><dd>${c.format[lang]}</dd></div><div><dt>${tr('Kategoria','Category')}</dt><dd>${c[lang]}</dd></div><div><dt>${tr('Prowadzenie','Led by')}</dt><dd>Agnieszka</dd></div><div><dt>${tr('Termin i dostęp','Dates and access')}</dt><dd>${tr('Do potwierdzenia','To be confirmed')}</dd></div></dl></div></section>
<section class="container product-info"><div><h2>${tr('O produkcie','About this product')}</h2><p>${productText(p)} ${tr('Pełny opis, program i forma dostępu zostaną uzupełnione przed uruchomieniem sprzedaży.','The full description, programme and access details will be added before sales begin.')}</p></div><div><h2>${tr('Co otrzymasz','What you\'ll receive')}</h2><ul>${includes.map(i=>`<li>${i}</li>`).join('')}</ul><p class="demo-caption">${tr('Przykładowa zawartość — do zatwierdzenia.','Example contents — subject to approval.')}</p></div><div><h2>${tr('Dla kogo?','Who is it for?')}</h2><p>${tr('Dla osób zainteresowanych tym tematem. Przed zgłoszeniem możesz zapytać o format, wymagania i przebieg.','For anyone interested in this topic. Before signing up, you can ask about the format, requirements and what to expect.')}</p></div></section>
<section class="container section related"><div class="section-heading"><h2>${tr('Może Cię też<br>zainteresować.','You may also<br>like.')}</h2><a class="text-link" href="/sklep/">${tr('Cały katalog','Full catalogue')}${arrow}</a></div><div class="shop-grid">${related.map(x=>productCard(x,'h3')).join('')}</div></section>`;}
function shopTeaser(){return `<section id="sklep" class="section container shop-teaser"><div class="section-heading"><h2>${tr('Dobre rzeczy<br>dla siebie.','Good things<br>for yourself.')}</h2><p>${tr('Warsztaty online i praktyki do wykonania w swoim tempie. Katalog pokazowy, zakupy online nie są jeszcze dostępne.','Online workshops and practices to explore at your own pace. Demo catalogue, online purchases are not yet available.')}</p></div><div class="shop-grid">${shopProducts('all',3,'h3')}</div><a class="button shop-teaser-cta" href="/sklep/">${tr('Zobacz sklep','Visit the shop')}<span class="arrow">${arrow}</span></a></section>`;}
let draft={name:'',email:'',phone:'',service:'help',event:'',message:''};
let opener=null,sendTimer=null;
function eventOptions(){const compatible=events.filter(e=>e.service===draft.service&&e.status!=='ended');return `<option value="">${tr('Bez konkretnego terminu','No specific date')}</option>`+compatible.map(e=>`<option value="${e.id}" ${draft.event===e.id?'selected':''}>${esc(e[lang])} — ${dateText(e.date)} (${tr('przykład','example')})</option>`).join('');}
function dialogs(){return `<dialog id="booking" aria-labelledby="booking-title"><div class="dialog-head"><button class="dialog-language" data-language>${tr('English','Po polsku')}</button><button class="close" data-close="booking" aria-label="${tr('Zamknij formularz','Close form')}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="booking-body"><h2 id="booking-title">${tr('Zacznijmy<br>od rozmowy.','Let\'s start<br>with a conversation.')}</h2><p class="form-intro">${tr('Wybierz usługę. Szczegóły spotkania ustalimy wspólnie.','Choose a service. We\'ll work out the session details together.')}</p><p class="form-demo">${tr('Tryb demonstracyjny — dane nie są wysyłane.','Demo mode — no data is sent.')}</p><form id="booking-form" novalidate><div class="field"><label for="service">${tr('Wybierz usługę','Choose a service')}</label><select id="service" name="service">${services.map(s=>`<option value="${s.id}" ${draft.service===s.id?'selected':''}>${esc(s[lang])}</option>`).join('')}</select></div><div class="field" id="event-field" ${events.some(e=>e.service===draft.service&&e.status!=='ended')?'':'hidden'}><label for="event">${tr('Wydarzenie / termin','Event / date')}</label><select id="event" name="event">${eventOptions()}</select></div><div class="field"><label for="name">${tr('Imię i nazwisko','Full name')} <span aria-hidden="true">*</span></label><input id="name" name="name" autocomplete="name" required maxlength="120" value="${esc(draft.name)}" aria-describedby="name-error"><p class="field-error" id="name-error" hidden></p></div><div class="field"><label for="email">${tr('Adres e-mail','Email address')} <span aria-hidden="true">*</span></label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254" value="${esc(draft.email)}" aria-describedby="email-error"><p class="field-error" id="email-error" hidden></p></div><div class="field"><label for="phone">${tr('Telefon (opcjonalnie)','Phone number (optional)')}</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40" value="${esc(draft.phone)}"></div><div class="field"><label for="message">${tr('Wiadomość (opcjonalnie)','Message (optional)')}</label><textarea id="message" name="message" rows="3" maxlength="1500" aria-describedby="message-help">${esc(draft.message)}</textarea><p id="message-help" class="field-help">${tr('Wystarczy pytanie organizacyjne. Nie wpisuj danych o zdrowiu.','A question about practical details is enough. Do not include health information.')}</p></div><p class="form-terms">${tr('Wysłanie formularza nie potwierdza terminu spotkania.','Submitting this form does not confirm your appointment.')} <button type="button" class="inline-link" data-info="privacy">${tr('Informacja o prywatności','Privacy information')}</button></p><button class="button submit-button" type="submit">${tr('Sprawdź zgłoszenie','Review your request')}<span class="arrow">${arrow}</span></button></form><div class="form-success" role="status" hidden><span class="success-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m5 12 4 4L19 6"/></svg></span><h3>${tr('Tak będzie wyglądać<br>potwierdzenie.','This is what your<br>confirmation will look like.')}</h3><p>${tr('To tylko demonstracja. Żadne dane nie zostały wysłane. W finalnej wersji zgłoszenie trafi na ustalony adres e-mail.','This is only a demonstration. No data has been sent. In the final version, your request will be sent to the agreed email address.')}</p><button class="button" data-close="booking">${tr('Wróć do strony','Back to the site')}</button></div></div></dialog><dialog id="information" aria-labelledby="info-title"><div class="dialog-head"><button class="close" data-close="information" aria-label="${tr('Zamknij','Close')}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="info-body"><h2 id="info-title"></h2><p id="info-copy"></p><button class="button" data-close="information">${tr('Rozumiem','Got it')}</button></div></dialog>`;}
function captureDraft(){const f=$('#booking-form');if(f&&!f.hidden)for(const k of Object.keys(draft)){const el=f.elements.namedItem(k);if(el)draft[k]=el.value;}}
function openBooking(id,event=''){captureDraft();$('.mobile-nav')?.classList.remove('open');$('.menu-toggle')?.setAttribute('aria-expanded','false');draft.service=services.some(s=>s.id===id)?id:'help';draft.event=events.some(e=>e.id===event&&e.service===draft.service&&e.status!=='ended')?event:'';opener=document.activeElement;$('#booking').remove();$('#information').remove();$('#app').insertAdjacentHTML('beforeend',dialogs());$('#booking').showModal();document.body.classList.add('dialog-open');$('#service').focus();}
function closeDialog(id){if(id==='booking'){clearTimeout(sendTimer);captureDraft();}$('#'+id).close();if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');if(id==='booking'&&opener?.isConnected)opener.focus();}
function openInfo(id){const privacy=id==='privacy',rules=id==='rules';$('#info-title').textContent=privacy?tr('Prywatność','Privacy'):rules?tr('Regulamin','Terms and conditions'):tr('Materiał w przygotowaniu','Content in preparation');$('#info-copy').textContent=privacy?tr('Ten lokalny prototyp nie wysyła danych z formularza. Przechowuje w przeglądarce wyłącznie wybór języka i wersji wyglądu. Finalna informacja o przetwarzaniu danych zostanie dodana przed uruchomieniem zapisów.','This local prototype does not send any form data. It only stores your language and design version preferences in your browser. Final information about how data is processed will be added before registration opens.'):rules?tr('Tutaj znajdzie się zatwierdzony regulamin. W prototypie nie są zawierane umowy ani dokonywane zakupy.','The approved terms and conditions will appear here. No contracts are entered into and no purchases are made in this prototype.'):tr('To podgląd miejsca na artykuł lub opis archiwalnego wydarzenia. Treść zostanie uzupełniona i zatwierdzona przed publikacją.','This is a placeholder for an article or a past event description. The content will be completed and approved before publication.');$('#information').showModal();document.body.classList.add('dialog-open');}
function versionSwitcher(){return `<nav class="version-switch" aria-label="${tr('Wersja wyglądu strony','Site design version')}"><span>${tr('Wersja','Version')}</span>${['1','2'].map(v=>`<a href="${location.pathname}?v=${v}&lang=${lang}" data-version="${v}" ${version===v?'aria-current="true"':''} aria-label="${tr('Otwórz wersję ','Open version ')}${v}">V${v}</a>`).join('')}</nav>`;}
function render(){const isWorkshop=location.pathname.startsWith('/warsztaty'),isShop=location.pathname.startsWith('/sklep'),theme2=version==='2',v2=theme2&&!isWorkshop&&!isShop;document.body.classList.toggle('inner-page',isWorkshop||isShop);document.body.classList.toggle('version-two',theme2);document.body.classList.toggle('product-view',isShop&&!!shopProductId());document.documentElement.lang=lang;document.title=tr('Agnieszka clarity — przestrzeń dla Ciebie','agnieszka clarity — a space for you');$('#app').innerHTML=(theme2?headerV2():header())+`<main id="main">${isWorkshop?workshopsPage():isShop?(shopProductId()?productPage(shopProductId()):shopPage()):v2?homeHeroV2()+homeSectionsV2():homeHero()+homeSections()}${theme2?contactV2():contact()}</main>`+footer()+(v2&&typeof heroSwitcher==='function'?heroSwitcher():'')+dialogs();}
function setLanguage(){const bookingOpen=$('#booking')?.open,finished=$('.form-success')&&!$('.form-success').hidden;clearTimeout(sendTimer);captureDraft();const openDetails=$$('details[open]').map(x=>x.id);const y=scrollY;lang=lang==='pl'?'en':'pl';try{localStorage.setItem('agnieszka-language',lang);}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render();openDetails.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});window.scrollTo({top:y,behavior:'instant'});if(bookingOpen){$('#booking').showModal();document.body.classList.add('dialog-open');if(finished){$('#booking-form').hidden=true;$('.form-intro').hidden=true;$('.form-success').hidden=false;}$('.dialog-language').focus();}}
function setVersion(next){if(next===version)return;captureDraft();const openDetails=$$('details[open]').map(x=>x.id);const anchor=$$('main>section[id]').filter(el=>el.getBoundingClientRect().top<=120).pop();const offset=anchor?anchor.getBoundingClientRect().top:0;version=next;try{localStorage.setItem('agnieszka-home-version',version);}catch{}const url=new URL(location.href);url.searchParams.set('v',version);history.replaceState(null,'',url);render();openDetails.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});const replacement=anchor&&document.getElementById(anchor.id);window.scrollTo({top:replacement?replacement.getBoundingClientRect().top+scrollY-offset:0,behavior:'instant'});$(`[data-version="${version}"]`).focus({preventScroll:true});}
document.addEventListener('click',e=>{
 const target=e.target;
 const variant=target.closest('[data-version]');if(variant){e.preventDefault();return setVersion(variant.dataset.version);}
 if(target.closest('[data-language]'))return setLanguage();
 const booking=target.closest('[data-book]');if(booking)return openBooking(booking.dataset.book,booking.dataset.event);
 const close=target.closest('[data-close]');if(close)return closeDialog(close.dataset.close);
 const info=target.closest('[data-info]');if(info)return openInfo(info.dataset.info);
 if(target.closest('.menu-toggle')){const open=$('.mobile-nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));return;}
 if(target.closest('.mobile-nav a')){$('.mobile-nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}
 const filter=target.closest('[data-event-filter]');if(filter){const key=filter.dataset.eventFilter;$$('[data-event-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter));});$('.event-results').innerHTML=events.filter(e=>key==='all'||(key==='ended'?e.status==='ended':e.format===key&&e.status!=='ended')).map(e=>eventCard(e)).join('');}
 const shop=target.closest('[data-shop-filter]');if(shop)applyShopFilter(shop.dataset.shopFilter);
});
document.addEventListener('change',e=>{if(e.target.id==='service'){captureDraft();draft.event='';$('#event').innerHTML=eventOptions();$('#event-field').hidden=!events.some(x=>x.service===draft.service&&x.status!=='ended');}});
document.addEventListener('toggle',e=>{if(e.target.matches('details')&&e.target.open){const group=e.target.closest('.accordion-group');if(group)$$('details[open]',group).forEach(d=>{if(d!==e.target)d.open=false;});}},true);
document.addEventListener('cancel',e=>{if(e.target.matches('dialog')){e.preventDefault();closeDialog(e.target.id);}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='booking-form')return;e.preventDefault();captureDraft();let first=null;for(const id of ['name','email']){const input=$('#'+id),error=$('#'+id+'-error');const invalid=id==='name'?!input.value.trim():!input.value.trim()||!input.validity.valid;input.setAttribute('aria-invalid',String(invalid));error.hidden=!invalid;error.textContent=id==='name'?tr('Wpisz imię i nazwisko.','Enter your full name.'):tr('Wpisz poprawny adres e-mail.','Enter a valid email address.');if(invalid&&!first)first=input;}if(first)return first.focus();const button=$('.submit-button');button.disabled=true;button.textContent=tr('Sprawdzanie…','Checking…');sendTimer=setTimeout(()=>{if(!$('#booking').open)return;$('#booking-form').hidden=true;$('.form-intro').hidden=true;$('.form-success').hidden=false;$('#booking-form').reset();draft={name:'',email:'',phone:'',service:'help',event:'',message:''};$('.form-success button').focus();},400);});
// 13.11.2026: the V2 hero entrance plays once per page load; later re-renders (language, version) show the hero at rest.
// Without JS the class never appears, so the hero is simply visible.
document.documentElement.classList.add('v2-hero-entrance');
render();
setTimeout(()=>document.documentElement.classList.remove('v2-hero-entrance'),3200);
